import { Component, inject, signal } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { MatButtonModule } from '@angular/material/button';
import { MatFormFieldModule } from '@angular/material/form-field';
import { MatInputModule } from '@angular/material/input';
import { MatSelectModule } from '@angular/material/select';
import { NotificationService } from '../../../../core/services/notification.service';

interface MockSchedule {
  id: string;
  reportType: string;
  frequency: string;
  recipients: string;
}

@Component({
  selector: 'app-mis-report-scheduled-tab',
  standalone: true,
  imports: [FormsModule, MatButtonModule, MatFormFieldModule, MatInputModule, MatSelectModule],
  templateUrl: './mis-report-scheduled-tab.component.html',
  styleUrl: './mis-report-scheduled-tab.component.scss',
})
export class MisReportScheduledTabComponent {
  private readonly notify = inject(NotificationService);

  readonly reportTypes = [
    'Executive dashboard',
    'Customer consent report',
    'Consent audit report',
    'Expiry report',
    'Revocation report',
    'Compliance overview',
    'Channel performance',
    'Maker performance',
    'TAT report',
  ];

  reportType = this.reportTypes[0];
  frequency: 'DAILY' | 'WEEKLY' | 'MONTHLY' = 'WEEKLY';
  dayOfWeek = 1;
  dayOfMonth = 1;
  recipients = '';
  format: 'CSV' | 'EXCEL' | 'PDF' = 'CSV';

  /** Placeholder list only — no backend persistence in this iteration. */
  readonly mockSchedules = signal<MockSchedule[]>([
    {
      id: 'mock-1',
      reportType: 'Executive dashboard',
      frequency: 'WEEKLY',
      recipients: 'compliance@example.com',
    },
    {
      id: 'mock-2',
      reportType: 'Customer consent report',
      frequency: 'MONTHLY',
      recipients: 'risk@example.com, ops@example.com',
    },
  ]);

  save(): void {
    const emails = this.recipients
      .split(',')
      .map((s) => s.trim())
      .filter(Boolean);
    const invalid = emails.some((e) => !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(e));
    if (emails.length === 0 || invalid) {
      this.notify.warning('Schedule', 'Enter valid comma-separated email addresses.');
      return;
    }
    this.notify.info('Scheduled reports', 'Scheduled reports coming soon');
  }
}
