import { DecimalPipe } from '@angular/common';
import { Component, OnDestroy, OnInit, computed, inject, signal } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { MatButtonModule } from '@angular/material/button';
import { MatProgressBarModule } from '@angular/material/progress-bar';
import { Subject, takeUntil } from 'rxjs';
import {
  AdminMisDashboard,
  MisConsentTrend,
  MisExecutiveKpis,
  MisTimeSeriesCountPoint,
} from '../../../../core/models/admin.model';
import { AdminService } from '../../../../core/services/admin.service';
import { LoggerService } from '../../../../core/services/logger.service';
import { NotificationService } from '../../../../core/services/notification.service';

@Component({
  selector: 'app-mis-report-executive-tab',
  standalone: true,
  imports: [DecimalPipe, FormsModule, MatButtonModule, MatProgressBarModule],
  templateUrl: './mis-report-executive-tab.component.html',
  styleUrl: './mis-report-executive-tab.component.scss',
})
export class MisReportExecutiveTabComponent implements OnInit, OnDestroy {
  private readonly adminApi = inject(AdminService);
  private readonly notify = inject(NotificationService);
  private readonly logger = inject(LoggerService);
  private readonly destroy$ = new Subject<void>();

  readonly loading = signal(true);
  readonly mis = signal<AdminMisDashboard | null>(null);
  readonly kpis = signal<MisExecutiveKpis | null>(null);
  readonly trendGroup = signal<'DAILY' | 'WEEKLY' | 'MONTHLY'>('MONTHLY');
  readonly trend = signal<MisConsentTrend | null>(null);
  readonly trendLoading = signal(false);

  readonly trendMax = computed(() => {
    const s = this.trend()?.series ?? [];
    return s.reduce((m, p) => Math.max(m, p.count), 1);
  });

  ngOnInit(): void {
    this.reloadAll();
  }

  ngOnDestroy(): void {
    this.destroy$.next();
    this.destroy$.complete();
  }

  reloadAll(): void {
    this.loading.set(true);
    this.adminApi
      .getMisDashboard()
      .pipe(takeUntil(this.destroy$))
      .subscribe({
        next: (res) => {
          if (res.success && res.data) {
            this.mis.set(res.data);
          }
        },
        error: (err) => this.logger.error('MisExecutive', 'mis dashboard', err),
      });
    this.adminApi
      .getMisExecutiveKpis()
      .pipe(takeUntil(this.destroy$))
      .subscribe({
        next: (res) => {
          this.loading.set(false);
          if (res.success && res.data) {
            this.kpis.set(res.data);
          } else {
            this.notify.warning('Executive KPIs', res.message || 'Could not load KPIs.');
          }
        },
        error: (err) => {
          this.loading.set(false);
          this.logger.error('MisExecutive', 'kpis', err);
          this.notify.error('Executive KPIs', err?.error?.message || 'Could not load KPIs.');
        },
      });
    this.loadTrend();
  }

  setTrendGroup(g: 'DAILY' | 'WEEKLY' | 'MONTHLY'): void {
    this.trendGroup.set(g);
    this.loadTrend();
  }

  loadTrend(): void {
    this.trendLoading.set(true);
    const to = new Date();
    const from = new Date();
    if (this.trendGroup() === 'DAILY') {
      from.setDate(from.getDate() - 30);
    } else if (this.trendGroup() === 'WEEKLY') {
      from.setMonth(from.getMonth() - 6);
    } else {
      from.setFullYear(from.getFullYear() - 2);
    }
    this.adminApi
      .getMisConsentTrend({
        groupBy: this.trendGroup(),
        fromDate: from.toISOString(),
        toDate: to.toISOString(),
      })
      .pipe(takeUntil(this.destroy$))
      .subscribe({
        next: (res) => {
          this.trendLoading.set(false);
          if (res.success && res.data) {
            this.trend.set(res.data);
          }
        },
        error: (err) => {
          this.trendLoading.set(false);
          this.logger.error('MisExecutive', 'trend', err);
          this.notify.error('Trend', err?.error?.message || 'Could not load consent trend.');
        },
      });
  }

  trendPoints(): MisTimeSeriesCountPoint[] {
    return this.trend()?.series ?? [];
  }

  trendSvgPolyline(): string {
    const pts = this.trendPoints();
    if (!pts.length) {
      return '';
    }
    const w = 600;
    const h = 160;
    const pad = 8;
    const max = this.trendMax();
    return pts
      .map((p, i) => {
        const x = pad + (i * (w - pad * 2)) / Math.max(1, pts.length - 1);
        const y = h - pad - (max === 0 ? 0 : (p.count / max) * (h - pad * 2));
        return `${x},${y}`;
      })
      .join(' ');
  }
}
