import { DatePipe, DecimalPipe } from '@angular/common';
import { Component, OnDestroy, OnInit, inject, signal } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { MatButtonModule } from '@angular/material/button';
import { MatCheckboxModule } from '@angular/material/checkbox';
import { MatFormFieldModule } from '@angular/material/form-field';
import { MatIconModule } from '@angular/material/icon';
import { MatInputModule } from '@angular/material/input';
import { MatProgressBarModule } from '@angular/material/progress-bar';
import { MatSelectModule } from '@angular/material/select';
import { Subject, takeUntil } from 'rxjs';
import { AuditLogEntry } from '../../../../core/models/audit.model';
import { MisComplianceOverview } from '../../../../core/models/admin.model';
import { AdminService } from '../../../../core/services/admin.service';
import { LoggerService } from '../../../../core/services/logger.service';
import { NotificationService } from '../../../../core/services/notification.service';

@Component({
  selector: 'app-mis-report-compliance-tab',
  standalone: true,
  imports: [
    DatePipe,
    DecimalPipe,
    FormsModule,
    MatButtonModule,
    MatCheckboxModule,
    MatFormFieldModule,
    MatInputModule,
    MatSelectModule,
    MatIconModule,
    MatProgressBarModule,
  ],
  templateUrl: './mis-report-compliance-tab.component.html',
  styleUrl: './mis-report-compliance-tab.component.scss',
})
export class MisReportComplianceTabComponent implements OnInit, OnDestroy {
  private readonly adminApi = inject(AdminService);
  private readonly notify = inject(NotificationService);
  private readonly logger = inject(LoggerService);
  private readonly destroy$ = new Subject<void>();

  /** No {@code USER_LOGIN} rows are written by the current backend audit pipeline. */
  readonly userLoginNote =
    'USER_LOGIN is not emitted to audit_logs today. Add an audit call on successful authentication to enable this filter.';

  readonly overview = signal<MisComplianceOverview | null>(null);
  readonly auditRows = signal<AuditLogEntry[]>([]);
  readonly actions = signal<string[]>([]);
  readonly loading = signal(false);
  readonly exporting = signal(false);
  readonly totalPages = signal(0);
  readonly currentPage = signal(0);
  readonly pageSize = 12;

  filterLoginOnly = false;
  filterConsentEntity = false;
  filterAdminActor = false;
  filterWorkflow = false;
  entityType = '';
  action = '';
  from = '';
  to = '';
  performedBy = '';

  ngOnInit(): void {
    this.adminApi
      .getMisComplianceOverview()
      .pipe(takeUntil(this.destroy$))
      .subscribe({
        next: (res) => {
          if (res.success && res.data) {
            this.overview.set(res.data);
          }
        },
        error: (e) => this.logger.error('MisCompliance', 'overview', e),
      });
    this.adminApi
      .getMisAuditActions()
      .pipe(takeUntil(this.destroy$))
      .subscribe({
        next: (res) => {
          if (res.success && res.data) {
            this.actions.set(res.data);
          }
        },
        error: (e) => this.logger.error('MisCompliance', 'actions', e),
      });
    this.load(0);
  }

  ngOnDestroy(): void {
    this.destroy$.next();
    this.destroy$.complete();
  }

  iso(s: string): string | undefined {
    return s ? new Date(s + 'T00:00:00').toISOString() : undefined;
  }

  isoEnd(s: string): string | undefined {
    return s ? new Date(s + 'T23:59:59').toISOString() : undefined;
  }

  load(page: number): void {
    this.loading.set(true);
    const et = this.filterConsentEntity ? 'CONSENT' : this.entityType || undefined;
    const ac = this.filterLoginOnly ? 'USER_LOGIN' : this.action || undefined;
    this.adminApi
      .getMisAuditReport({
        page,
        size: this.pageSize,
        entityType: et,
        action: ac,
        fromDate: this.iso(this.from),
        toDate: this.isoEnd(this.to),
        performedBy: this.performedBy.trim() || undefined,
        workflowActionsOnly: this.filterWorkflow || undefined,
        adminActorOnly: this.filterAdminActor || undefined,
      })
      .pipe(takeUntil(this.destroy$))
      .subscribe({
        next: (res) => {
          this.loading.set(false);
          if (res.success && res.data) {
            this.auditRows.set(res.data.content);
            this.totalPages.set(res.data.totalPages);
            this.currentPage.set(res.data.currentPage);
          }
        },
        error: (err) => {
          this.loading.set(false);
          this.notify.error('Compliance audit', err?.error?.message || 'Load failed.');
        },
      });
  }

  apply(): void {
    this.load(0);
  }

  prev(): void {
    const p = this.currentPage();
    if (p > 0) {
      this.load(p - 1);
    }
  }

  next(): void {
    const p = this.currentPage();
    if (p < this.totalPages() - 1) {
      this.load(p + 1);
    }
  }

  private dl(blob: Blob, n: string): void {
    const u = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = u;
    a.download = n;
    a.click();
    URL.revokeObjectURL(u);
  }

  exportCsv(): void {
    this.exporting.set(true);
    const et = this.filterConsentEntity ? 'CONSENT' : this.entityType || undefined;
    const ac = this.filterLoginOnly ? 'USER_LOGIN' : this.action || undefined;
    this.adminApi
      .exportMisAuditCsv({
        entityType: et,
        action: ac,
        fromDate: this.iso(this.from),
        toDate: this.isoEnd(this.to),
        performedBy: this.performedBy.trim() || undefined,
        workflowActionsOnly: this.filterWorkflow || undefined,
        adminActorOnly: this.filterAdminActor || undefined,
      })
      .pipe(takeUntil(this.destroy$))
      .subscribe({
        next: (b) => {
          this.exporting.set(false);
          this.dl(b, 'compliance-audit.csv');
          this.notify.success('Export', 'CSV started.');
        },
        error: () => {
          this.exporting.set(false);
          this.notify.error('Export', 'Failed.');
        },
      });
  }

  exportExcel(): void {
    this.exporting.set(true);
    const et = this.filterConsentEntity ? 'CONSENT' : this.entityType || undefined;
    const ac = this.filterLoginOnly ? 'USER_LOGIN' : this.action || undefined;
    this.adminApi
      .exportMisAuditExcel({
        entityType: et,
        action: ac,
        fromDate: this.iso(this.from),
        toDate: this.isoEnd(this.to),
        performedBy: this.performedBy.trim() || undefined,
        workflowActionsOnly: this.filterWorkflow || undefined,
        adminActorOnly: this.filterAdminActor || undefined,
      })
      .pipe(takeUntil(this.destroy$))
      .subscribe({
        next: (b) => {
          this.exporting.set(false);
          this.dl(b, 'compliance-audit.xlsx');
          this.notify.success('Export', 'Excel started.');
        },
        error: () => {
          this.exporting.set(false);
          this.notify.error('Export', 'Failed.');
        },
      });
  }
}
