import { DecimalPipe } from '@angular/common';
import { Component, OnDestroy, OnInit, computed, inject, signal } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { MatButtonModule } from '@angular/material/button';
import { MatTooltipModule } from '@angular/material/tooltip';
import { Subject, takeUntil } from 'rxjs';

import {
  MisActiveConsentsTimeline,
  MisTimeSeriesCountPoint
} from '../../../../core/models/admin.model';

import { AdminService } from '../../../../core/services/admin.service';
import { LoggerService } from '../../../../core/services/logger.service';
import { NotificationService } from '../../../../core/services/notification.service';

interface DotPoint extends MisTimeSeriesCountPoint {
  x: number;
  y: number;
}

@Component({
  selector: 'app-mis-report-active-consents-tab',
  standalone: true,
  imports: [DecimalPipe, FormsModule, MatButtonModule, MatTooltipModule],
  templateUrl: './mis-report-active-consents-tab.component.html',
  styleUrl: './mis-report-active-consents-tab.component.scss',
})
export class MisReportActiveConsentsTabComponent implements OnInit, OnDestroy {
  private readonly adminApi = inject(AdminService);
  private readonly notify = inject(NotificationService);
  private readonly logger = inject(LoggerService);
  private readonly destroy$ = new Subject<void>();

  readonly data = signal<MisActiveConsentsTimeline | null>(null);
  readonly loading = signal(false);

  groupBy: 'DAILY' | 'WEEKLY' | 'MONTHLY' = 'MONTHLY';
  from = '';
  to = '';

  // ── SVG geometry constants ──────────────────────────────────────────────────
  private readonly W = 620;
  private readonly H = 180;
  private readonly PAD = 10;

  // ── Computed max ────────────────────────────────────────────────────────────
  readonly trendMax = computed(() => {
    const s = this.data()?.series ?? [];
    return s.reduce((m, p) => Math.max(m, p.count), 1);
  });

  // ── Lifecycle ───────────────────────────────────────────────────────────────
  ngOnInit(): void {
    this.reload();
  }

  ngOnDestroy(): void {
    this.destroy$.next();
    this.destroy$.complete();
  }

  // ── Date helpers ────────────────────────────────────────────────────────────
  isoStart(s: string): string | undefined {
    return s ? new Date(s + 'T00:00:00').toISOString() : undefined;
  }

  isoEnd(s: string): string | undefined {
    return s ? new Date(s + 'T23:59:59').toISOString() : undefined;
  }

  // ── API ─────────────────────────────────────────────────────────────────────
  reload(): void {
    this.loading.set(true);

    this.adminApi
      .getMisActiveConsentsTimeline({
        groupBy: this.groupBy,
        fromDate: this.isoStart(this.from),
        toDate: this.isoEnd(this.to),
      })
      .pipe(takeUntil(this.destroy$))
      .subscribe({
        next: (res) => {
          this.loading.set(false);

          if (res.success && res.data) {
            this.data.set(res.data);
          }
        },
        error: (e) => {
          this.loading.set(false);
          this.logger.error('MisActive', 'timeline', e);
          this.notify.error(
            'Active consents',
            e?.error?.message ?? 'Load failed.'
          );
        },
      });
  }

  // ── Point helpers ───────────────────────────────────────────────────────────
  points(): MisTimeSeriesCountPoint[] {
    return this.data()?.series ?? [];
  }

  /** Shared (x, y) calculation for a point at index i */
  private ptCoords(i: number, count: number): { x: number; y: number } {
    const pts = this.points();
    const max = this.trendMax();

    const x =
      this.PAD +
      (i * (this.W - this.PAD * 2)) / Math.max(1, pts.length - 1);

    const y =
      this.H -
      this.PAD -
      (max === 0
        ? 0
        : (count / max) * (this.H - this.PAD * 2));

    return { x, y };
  }

  /** Polyline string for the line stroke */
  polyline(): string {
    return this.points()
      .map((p, i) => {
        const { x, y } = this.ptCoords(i, p.count);
        return `${x},${y}`;
      })
      .join(' ');
  }

  /** Polygon string for the area fill */
  areaPolygon(): string {
    const pts = this.points();

    if (!pts.length) {
      return '';
    }

    const top = pts
      .map((p, i) => {
        const { x, y } = this.ptCoords(i, p.count);
        return `${x},${y}`;
      })
      .join(' ');

    return `${this.PAD},${this.H - this.PAD} ${top} ${this.W - this.PAD},${this.H - this.PAD}`;
  }

  /** Pre-computed dot positions for interactive circles */
  dotPoints(): DotPoint[] {
    return this.points().map((p, i) => {
      const { x, y } = this.ptCoords(i, p.count);
      return { ...p, x, y };
    });
  }

  /** ▲ / ▼ / — trend arrow */
  trendArrow(delta: number | null | undefined): string {
    if (delta == null) {
      return '—';
    }

    return delta >= 0 ? '▲' : '▼';
  }
}

