import { DatePipe, DecimalPipe } from '@angular/common';
import { Component, OnDestroy, OnInit, inject, signal } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { MatButtonModule } from '@angular/material/button';
import { MatIconModule } from '@angular/material/icon';
import { MatTooltipModule } from '@angular/material/tooltip';
import { Subject, forkJoin, takeUntil } from 'rxjs';
import {
  MisDemographicGeo,
  MisDemographicLifecycle,
  MisDemographicVipSplit,
  MisReEngagementFunnel,
} from '../../../../core/models/admin.model';
import { AdminService } from '../../../../core/services/admin.service';
import { LoggerService } from '../../../../core/services/logger.service';
import { NotificationService } from '../../../../core/services/notification.service';

@Component({
  selector: 'app-mis-report-demographics-tab',
  standalone: true,
  imports: [DatePipe, DecimalPipe, FormsModule, MatButtonModule, MatIconModule, MatTooltipModule],
  templateUrl: './mis-report-demographics-tab.component.html',
  styleUrl: './mis-report-demographics-tab.component.scss',
})
export class MisReportDemographicsTabComponent implements OnInit, OnDestroy {
  private readonly adminApi = inject(AdminService);
  private readonly notify = inject(NotificationService);
  private readonly logger = inject(LoggerService);
  private readonly destroy$ = new Subject<void>();

  readonly loading = signal(false);
  readonly vip = signal<MisDemographicVipSplit | null>(null);
  readonly lifecycle = signal<MisDemographicLifecycle | null>(null);
  readonly funnel = signal<MisReEngagementFunnel | null>(null);
  readonly geo = signal<MisDemographicGeo | null>(null);

  lifeFrom = '';
  lifeTo = '';

  ngOnInit(): void {
    this.reloadLifecycle();
  }

  ngOnDestroy(): void {
    this.destroy$.next();
    this.destroy$.complete();
  }

  isoStart(s: string): string | undefined {
    return s ? new Date(s + 'T00:00:00').toISOString() : undefined;
  }

  isoEnd(s: string): string | undefined {
    return s ? new Date(s + 'T23:59:59').toISOString() : undefined;
  }

  reloadLifecycle(): void {
    this.loading.set(true);
    forkJoin({
      vip: this.adminApi.getMisDemographicVipSplit(),
      life: this.adminApi.getMisDemographicLifecycle({
        fromDate: this.isoStart(this.lifeFrom),
        toDate: this.isoEnd(this.lifeTo),
      }),
      funnel: this.adminApi.getMisReEngagementFunnel(),
      geo: this.adminApi.getMisDemographicGeo(),
    })
      .pipe(takeUntil(this.destroy$))
      .subscribe({
        next: ({ vip, life, funnel, geo }) => {
          this.loading.set(false);
          if (vip.success && vip.data) this.vip.set(vip.data);
          if (life.success && life.data) this.lifecycle.set(life.data);
          if (funnel.success && funnel.data) this.funnel.set(funnel.data);
          if (geo.success && geo.data) this.geo.set(geo.data);
        },
        error: (e) => {
          this.loading.set(false);
          this.logger.error('MisDemo', 'load', e);
          this.notify.error('Demographics', e?.error?.message ?? 'Load failed.');
        },
      });
  }

  applyLife(): void {
    this.reloadLifecycle();
  }

  funnelMax(): number {
    const f = this.funnel();
    if (!f) return 1;
    return Math.max(1, f.invitedCustomers, f.pendingNoResponse, f.accepted, f.declinedOrWithdrawn);
  }

  funnelPct(v: number): number {
    return (v / this.funnelMax()) * 100;
  }
}