import { DatePipe } from '@angular/common';
import { Component, OnDestroy, OnInit, computed, inject, signal } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { MatButtonModule } from '@angular/material/button';
import { MatFormFieldModule } from '@angular/material/form-field';
import { MatIconModule } from '@angular/material/icon';
import { MatInputModule } from '@angular/material/input';
import { MatProgressBarModule } from '@angular/material/progress-bar';
import { MatSelectModule } from '@angular/material/select';
import { Subject, takeUntil } from 'rxjs';
import {
  MisRevocationReportRow,
  MisTimeSeriesCountPoint,
  customerConsentRecordStatusLabel,
} from '../../../../core/models/admin.model';
import { AdminService } from '../../../../core/services/admin.service';
import { LoggerService } from '../../../../core/services/logger.service';
import { NotificationService } from '../../../../core/services/notification.service';

@Component({
  selector: 'app-mis-report-revocation-tab',
  standalone: true,
  imports: [
    DatePipe,
    FormsModule,
    MatButtonModule,
    MatFormFieldModule,
    MatInputModule,
    MatSelectModule,
    MatIconModule,
    MatProgressBarModule,
  ],
  templateUrl: './mis-report-revocation-tab.component.html',
  styleUrl: './mis-report-revocation-tab.component.scss',
})
export class MisReportRevocationTabComponent implements OnInit, OnDestroy {
  private readonly adminApi = inject(AdminService);
  private readonly notify = inject(NotificationService);
  private readonly logger = inject(LoggerService);
  private readonly destroy$ = new Subject<void>();

  readonly series = signal<MisTimeSeriesCountPoint[]>([]);
  readonly rows = signal<MisRevocationReportRow[]>([]);
  readonly loading = signal(false);
  readonly exporting = signal(false);
  readonly totalPages = signal(0);
  readonly currentPage = signal(0);
  readonly pageSize = 10;

  from = '';
  to = '';
  vipFilter: '' | 'true' | 'false' = '';

  readonly chartMax = computed(() => this.series().reduce((m, p) => Math.max(m, p.count), 1));

  ngOnInit(): void {
    this.adminApi
      .getMisRevocationTrend()
      .pipe(takeUntil(this.destroy$))
      .subscribe({
        next: (res) => {
          if (res.success && res.data) this.series.set(res.data.series);
        },
        error: (e) => this.logger.error('MisRevocation', 'trend', e),
      });
    this.load(0);
  }

  ngOnDestroy(): void {
    this.destroy$.next();
    this.destroy$.complete();
  }

  isoStart(s: string): string | undefined {
    return s ? new Date(s + 'T00:00:00').toISOString() : undefined;
  }

  isoEnd(s: string): string | undefined {
    return s ? new Date(s + 'T23:59:59').toISOString() : undefined;
  }

  vipBool(): boolean | undefined {
    if (this.vipFilter === 'true') return true;
    if (this.vipFilter === 'false') return false;
    return undefined;
  }

  load(page: number): void {
    this.loading.set(true);
    this.adminApi
      .getMisRevocationReport({
        page,
        size: this.pageSize,
        fromDate: this.isoStart(this.from),
        toDate: this.isoEnd(this.to),
        vip: this.vipBool(),
      })
      .pipe(takeUntil(this.destroy$))
      .subscribe({
        next: (res) => {
          this.loading.set(false);
          if (res.success && res.data) {
            this.rows.set(res.data.content);
            this.totalPages.set(res.data.totalPages);
            this.currentPage.set(res.data.currentPage);
          }
        },
        error: (err) => {
          this.loading.set(false);
          this.notify.error('Revocation', err?.error?.message || 'Load failed.');
        },
      });
  }

  apply(): void { this.load(0); }

  prev(): void {
    const p = this.currentPage();
    if (p > 0) this.load(p - 1);
  }

  next(): void {
    const p = this.currentPage();
    if (p < this.totalPages() - 1) this.load(p + 1);
  }

  label(s: string | null | undefined): string {
    return customerConsentRecordStatusLabel(s);
  }

  barHeight(c: number): number {
    const m = this.chartMax();
    if (m === 0) return 0;
    return Math.round((c / m) * 120);
  }

  private dl(blob: Blob, n: string): void {
    const u = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = u;
    a.download = n;
    a.click();
    URL.revokeObjectURL(u);
  }

  exportCsv(): void {
    this.exporting.set(true);
    this.adminApi
      .exportMisRevocationCsv({ fromDate: this.isoStart(this.from), toDate: this.isoEnd(this.to), vip: this.vipBool() })
      .pipe(takeUntil(this.destroy$))
      .subscribe({
        next: (b) => {
          this.exporting.set(false);
          this.dl(b, 'revocation-report.csv');
          this.notify.success('Export', 'CSV started.');
        },
        error: () => {
          this.exporting.set(false);
          this.notify.error('Export', 'Failed.');
        },
      });
  }

  exportExcel(): void {
    this.exporting.set(true);
    this.adminApi
      .exportMisRevocationExcel({ fromDate: this.isoStart(this.from), toDate: this.isoEnd(this.to), vip: this.vipBool() })
      .pipe(takeUntil(this.destroy$))
      .subscribe({
        next: (b) => {
          this.exporting.set(false);
          this.dl(b, 'revocation-report.xlsx');
          this.notify.success('Export', 'Excel started.');
        },
        error: () => {
          this.exporting.set(false);
          this.notify.error('Export', 'Failed.');
        },
      });
  }
}